"""Copy every payout from the Tallyline Payouts API into payouts.jsonl."""
import argparse
import json
import time
import urllib.error
import urllib.parse
import urllib.request

PAGE_LIMIT = 1000


def fetch_page(base_url, cursor):
    """Fetch one v2 export window, retrying 429s with the same request."""
    params = {"limit": str(PAGE_LIMIT)}
    if cursor is not None:
        params["cursor"] = cursor
    url = f"{base_url}/v2/payouts?{urllib.parse.urlencode(params)}"
    while True:
        try:
            with urllib.request.urlopen(url, timeout=30) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as exc:
            if exc.code != 429:
                raise
            retry_after = exc.headers.get("Retry-After", "1")
            try:
                delay = max(0.0, float(retry_after))
            except ValueError:
                delay = 1.0
            time.sleep(delay)


def fetch_payouts(base_url):
    """Follow the export cursor to drained, deduplicating overlapping windows."""
    seen = set()
    payouts = []
    cursor = None
    while True:
        try:
            page = fetch_page(base_url, cursor)
        except urllib.error.HTTPError as exc:
            if exc.code == 400 and cursor is not None:
                try:
                    error = json.loads(exc.read()).get("error")
                except (ValueError, AttributeError):
                    error = None
                if error == "invalid_cursor":
                    # Restart the export; already-seen ids are deduplicated.
                    cursor = None
                    continue
            raise

        for payout in page["payouts"]:
            payout_id = payout["id"]
            if payout_id not in seen:
                seen.add(payout_id)
                payouts.append(payout)

        if page["drained"]:
            return payouts
        cursor = page["cursor"]


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-url", required=True)
    ap.add_argument("--out", default="payouts.jsonl")
    args = ap.parse_args()
    payouts = fetch_payouts(args.base_url.rstrip("/"))
    with open(args.out, "w") as f:
        for p in payouts:
            f.write(json.dumps(p) + "\n")
    print(f"synced {len(payouts)} payouts")


if __name__ == "__main__":
    main()

